fn b_add(_: &mut Evaluator,a:&[Value])->Result<Value>{let mut int_acc=0i64; let mut all_int=true; for (i,v) in a.iter().enumerate(){if let Value::Int(n)=v{if let Some(sum)=int_acc.checked_add(*n){int_acc=sum;}else{all_int=false;}}else{all_int=false; if !matches!(v,Value::RationalValue(_)|Value::Float(_)|Value::ComplexValue(_)|Value::NumberLiteral(_,_)){return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("+"),Value::Int((i+1) as i64),v.clone(),Value::string(if matches!(v,Value::Undefined){"an undefined object"}else if matches!(v,Value::Bool(_)){"boolean"}else{value_kind(v)}),Value::string("a number")]));}}} if all_int{return Ok(Value::Int(int_acc));} fold_num(a,Value::Int(0),add2)} fn b_mul(_: &mut Evaluator,a:&[Value])->Result<Value>{let mut int_acc=1i64; let mut all_int=true; for v in a{if let Value::Int(n)=v{if let Some(prod)=int_acc.checked_mul(*n){int_acc=prod;}else{all_int=false;break;}}else{all_int=false;break;}} if all_int{return Ok(Value::Int(int_acc));} fold_num(a,Value::Int(1),mul2)}
fn b_sub(_: &mut Evaluator,a:&[Value])->Result<Value>{ if a.len()==1{if matches!(a[0],Value::Int(i64::MIN)){return Err(most_negative_negation_error())}sub2(Value::Int(0),a[0].clone())}else{fold_num(&a[1..],a[0].clone(),sub2)} }
fn b_div(_: &mut Evaluator,a:&[Value])->Result<Value>{ let r=if a.len()==1{div2(Value::Int(1),a[0].clone())}else{fold_num(&a[1..],a[0].clone(),div2)}; r.map_err(|e|if e.tag=="division-by-zero" && a.len()>=2{SchemeError::new("division-by-zero",vec![Value::string("~A: division by zero, (~A ~S ~S)"),Value::symbol("/"),Value::symbol("/"),a[0].clone(),a[1].clone()])}else{e}) }
fn int_cmp(a:&[Value], f:fn(i64,i64)->bool)->Option<Value>{let mut it=a.iter(); let mut prev=match it.next(){Some(Value::Int(n))=>*n,Some(_)=>return None,None=>return Some(Value::Bool(true))}; for v in it{let Value::Int(n)=v else{return None}; if !f(prev,*n){return Some(Value::Bool(false));} prev=*n;} Some(Value::Bool(true))}
fn b_eqnum(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Some(v)=int_cmp(a,|x,y|x==y){return Ok(v);} for w in a.windows(2){let (ar,ai)=to_complex(&w[0])?; let (br,bi)=to_complex(&w[1])?; if ar!=br||ai!=bi{return Ok(Value::Bool(false));}} Ok(Value::Bool(true))} fn b_lt(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Some(v)=int_cmp(a,|x,y|x<y){return Ok(v);} cmp(a,|x,y|x<y)} fn b_gt(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Some(v)=int_cmp(a,|x,y|x>y){return Ok(v);} cmp(a,|x,y|x>y)} fn b_le(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Some(v)=int_cmp(a,|x,y|x<=y){return Ok(v);} cmp(a,|x,y|x<=y)} fn b_ge(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Some(v)=int_cmp(a,|x,y|x>=y){return Ok(v);} cmp(a,|x,y|x>=y)}
fn round_even(x:f64)->i64{let fl=x.floor(); let frac=x-fl; if (frac-0.5).abs()<1e-12 { if (fl as i64)%2==0 {fl as i64}else{fl as i64+1} } else { x.round() as i64 }}
