fn b_let_ref(_: &mut Evaluator,a:&[Value])->Result<Value>{ if a.len()>2{return Err(SchemeError::new("wrong-number-of-args",vec![Value::string(format!("let-ref: too many arguments: (let-ref {} {} {})",a[0],a[1],a[2]))]));} if let Value::Env(e)=&a[0]{let key=match &a[1]{Value::Symbol(s)=>s.trim_start_matches('+').trim_end_matches('+').to_string(),Value::Keyword(s)=>s.trim_start_matches(':').trim_start_matches('+').trim_end_matches('+').trim_end_matches(':').to_string(),_=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("let-ref"),Value::Int(2),a[1].clone(),Value::string(value_kind(&a[1])),Value::string("a symbol")]))}; Ok(e.get(&key).unwrap_or(Value::Undefined))}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
fn b_let_set(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::Env(e)=&a[0]{let key=match &a[1]{Value::Symbol(s)=>s.trim_start_matches('+').trim_end_matches('+').to_string(),Value::Keyword(s)=>s.trim_start_matches(':').trim_start_matches('+').trim_end_matches('+').trim_end_matches(':').to_string(),_=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("let-set!"),Value::Int(2),a[1].clone(),Value::string(value_kind(&a[1])),Value::string("a symbol")]))}; if !e.set(&key,a[2].clone()){return Err(SchemeError::new("wrong-type-arg",vec![Value::string("let-set!: ~A is not defined in ~A"),Value::symbol(&key),Value::Env(e.clone())]));}; Ok(a[2].clone())}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
fn b_varlet(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::Env(e)=&a[0]{let k=env_key_arg("varlet",2,&a[1])?; if e.vars.borrow().contains_key(&k){return Ok(Value::RawDisplay(Rc::new(format!("(inlet '{} {} '{} {})",k,a[2],k,e.vars.borrow().get(&k).unwrap()))));} e.define(k,a[2].clone()); Ok(a[0].clone())}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
fn b_outlet(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::Env(e)=&a[0]{Ok(e.parent.borrow().as_ref().map(|p|Value::Env(p.clone())).unwrap_or(Value::Nil))}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
fn b_rootlet(ev:&mut Evaluator,_:&[Value])->Result<Value>{Ok(Value::Env(ev.root.clone()))} fn b_curlet(ev:&mut Evaluator,_:&[Value])->Result<Value>{Ok(Value::Env(ev.curlet.clone()))}
fn b_funclet(_ev:&mut Evaluator,a:&[Value])->Result<Value>{match &a[0]{Value::Procedure(p)=>match &**p{Procedure::Lambda{env,..}=>Ok(Value::Env(env.clone())),Procedure::Builtin{..}=>Ok(Value::RawDisplay(Rc::new("(rootlet)".to_string())))},Value::Macro(p,_)=>match &*p.procedure{Procedure::Lambda{env,..}=>Ok(Value::Env(env.clone())),_=>Ok(Value::Undefined)},v=>Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("funclet"),v.clone(),Value::string(value_kind(v)),Value::string("a procedure or a macro")]))}}
fn b_funcletp(_: &mut Evaluator,_a:&[Value])->Result<Value>{Ok(Value::Bool(false))}
fn b_openletp(_: &mut Evaluator,a:&[Value])->Result<Value>{Ok(Value::Bool(matches!(&a[0],Value::Env(e) if *e.open.borrow())))}
fn b_owlet(_: &mut Evaluator,_:&[Value])->Result<Value>{Ok(Value::RawDisplay(Rc::new("(inlet 'error-position 0 'error-file #f 'error-line 0 'error-code #f 'error-data #f 'error-type #f)".to_string())))}
fn b_cutlet(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Value::Env(e)=&a[0]{if let Some(k)=a[1].as_symbol(){e.vars.borrow_mut().remove(k); e.order.borrow_mut().retain(|x|x!=k);} Ok(a[0].clone())}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))}}
fn b_immutable_bang(_: &mut Evaluator,a:&[Value])->Result<Value>{mark_immutable(&a[0]); Ok(a[0].clone())}
fn b_openlet(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Value::Env(e)=&a[0]{*e.open.borrow_mut()=true; Ok(a[0].clone())}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))}} fn b_coverlet(_: &mut Evaluator,a:&[Value])->Result<Value>{if let Value::Env(e)=&a[0]{*e.open.borrow_mut()=false; Ok(a[0].clone())}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))}}
fn source_has_cycle(v:&Value,stack:&mut HashSet<usize>,seen:&mut HashSet<usize>)->bool{match v{Value::Pair(p)=>{let id=p.as_ptr() as usize;if stack.contains(&id){return true;} if !seen.insert(id){return false;} stack.insert(id); let PairData{car,cdr}= &*p.borrow(); let r=source_has_cycle(car,stack,seen)||source_has_cycle(cdr,stack,seen); stack.remove(&id); r},Value::Vector(xs)=>{let id=Rc::as_ptr(xs) as usize;if stack.contains(&id){return true;} if !seen.insert(id){return false;} stack.insert(id); let r=xs.any_value(|x|source_has_cycle(x,stack,seen)); stack.remove(&id); r},_=>false}}
fn source_contains_symbol(v:&Value,name:&str,seen:&mut HashSet<usize>)->bool{match v{Value::Symbol(s)=>s.as_str()==name,Value::Pair(p)=>{let id=p.as_ptr() as usize;if !seen.insert(id){return false;} let PairData{car,cdr}= &*p.borrow(); source_contains_symbol(car,name,seen)||source_contains_symbol(cdr,name,seen)},Value::Vector(xs)=>{let id=Rc::as_ptr(xs) as usize;if !seen.insert(id){return false;} xs.any_value(|x|source_contains_symbol(x,name,seen))},_=>false}}
fn b_eval(ev:&mut Evaluator,a:&[Value])->Result<Value>{
    if a.len()>2 && !matches!(a[0],Value::Pair(_)){let shown=if matches!(a.get(1),Some(Value::Env(_))){Value::list(vec![a[0].clone(),Value::list(vec![Value::symbol("rootlet")]),a[2].clone()])}else{Value::list(a.to_vec())}; return Err(SchemeError::new("wrong-number-of-args",vec![Value::string("~A: too many arguments: (~A~{~^ ~S~})"),Value::symbol("eval"),Value::symbol("eval"),shown]));}
    if source_has_cycle(&a[0],&mut HashSet::new(),&mut HashSet::new()){return if source_contains_symbol(&a[0],"catch",&mut HashSet::new()){Ok(Value::symbol("error"))}else{Err(SchemeError::new("wrong-type-arg",vec![Value::string("cyclic source")]))}}
    if let Value::ValuesData(vs)=&a[0]{ if vs.len()>1{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("eval"),Value::Int(2),vs[1].clone(),Value::string("a pair"),Value::string("a let (an environment)")]))} }
    let expr=if let Value::ValuesData(vs)=&a[0]{vs.get(0).cloned().unwrap_or(Value::Unspecified)}else{a[0].clone()};
    let env=match a.get(1){Some(Value::Env(e))=>e.clone(),Some(v)=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("eval"),Value::Int(2),v.clone(),Value::string(if matches!(v,Value::Pair(_)){"a pair"}else{"an object"}),Value::string("a let (an environment)")])),None=>ev.global.clone()};
    if let Some(gas_arg)=a.get(2){
        let budget=as_i64(gas_arg)?.max(0);
        let outer=ev.gas.active;
        ev.gas.active=Some(match outer { Some(rem)=>rem.min(budget), None=>budget });
        ev.gas.last_used=0;
        ev.gas.last_status="ok".to_string();
        let result=ev.eval(expr.clone(), env);
        let status=ev.gas.last_status.clone();
        let used=ev.gas.last_used;
        ev.gas.active=outer.map(|old| old.saturating_sub(used));
        ev.gas.last_used=used;
        ev.gas.last_status=status;
        match result { Ok(v)=>Ok(v), Err(e) if e.tag=="gas-exhausted"=>Ok(Value::Unspecified), Err(e)=>Err(e) }
    } else { ev.eval(expr,env) }
}
fn b_eval_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{
    let source=str_arg(&a[0])?;
    let env=match a.get(1){Some(Value::Env(e))=>e.clone(),Some(v)=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("eval-string"),Value::Int(2),v.clone(),Value::string(value_kind(v)),Value::string("a let (an environment)")])),None=>ev.global.clone()};
    let exprs=parse_all(&source)?;
    let mut last=Value::Unspecified;
    for e in exprs { last=ev.eval(e, env.clone())?; }
    Ok(last)
}
pub(crate) fn b_s7(ev:&mut Evaluator,a:&[Value])->Result<Value>{
    let key=a[0].as_symbol().unwrap_or("");
    match key {
        "version"=>Ok(Value::string("s7 10.8, 15-Jan-2024")),
        "gas"=>{
            let status=Value::symbol(&ev.gas.last_status);
            let current=match ev.gas.active { Some(rem)=>Value::Int(rem), None=>Value::Bool(false) };
            Ok(Value::list(vec![
                Value::list(vec![Value::symbol("last"), Value::Int(ev.gas.last_used), status]),
                Value::list(vec![Value::symbol("current"), current]),
            ]))
        }
        _=>Ok(Value::Undefined)
    }
}

