fn b_close_port(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Some(Value::Port(p))=a.get(0){ match &mut *p.borrow_mut(){ Port::Input{text,pos,repr}=>{ *pos=text.len(); *repr=PortRepr::ClosedInput; }, Port::Output{repr,..}=>{ if *repr==PortRepr::OpenOutput{*repr=PortRepr::ClosedOutput;} } } } Ok(Value::Unspecified)}
fn b_open_input_string(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::String(s)=&a[0]{Ok(Value::Port(Rc::new(RefCell::new(Port::Input{text:s.borrow().chars().collect(),pos:0,repr:PortRepr::OpenInput}))))}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
