fn b_get_output_string(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::Port(p)=&a[0]{ if let Port::Output{text,repr}= &*p.borrow(){if *repr==PortRepr::ClosedOutput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("get-output-string"),Value::Int(1),a[0].clone(),Value::string("an output port"),Value::string("an open string output port or #f")]))} Ok(Value::string(text.clone()))}else{Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("get-output-string"),Value::Int(1),a[0].clone(),Value::string("an input port"),Value::string("an open string output port or #f")]))}}else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))}}
fn b_call_with_output_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=b_open_output_string(ev,&[])?; ev.apply_value(a[0].clone(),vec![p.clone()],ev.global.clone())?; b_get_output_string(ev,&[p])}
fn b_with_output_to_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{let old=ev.stdout.clone(); let p=b_open_output_string(ev,&[])?; ev.stdout=p.clone(); let res=ev.apply_value(a[0].clone(),vec![],ev.global.clone()); ev.stdout=old; res?; b_get_output_string(ev,&[p])}
fn b_call_with_input_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=if let Value::String(s)=&a[0]{Value::Port(Rc::new(RefCell::new(Port::Input{text:s.borrow().chars().collect(),pos:0,repr:PortRepr::CallWithInput})))}else{return Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]));}; let r=ev.apply_value(a[1].clone(),vec![p.clone()],ev.global.clone()); if let Value::Port(port)=&p{ if let Port::Input{text,pos,..}=&mut *port.borrow_mut(){*pos=text.len();} } r}
fn b_with_input_from_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{let old=ev.stdin.clone(); ev.stdin=b_open_input_string(ev,&[a[0].clone()])?; let res=ev.apply_value(a[1].clone(),vec![],ev.global.clone()); ev.stdin=old; res}
pub(crate) fn set_port_position(port:&Value,n:usize)->Result<()> { if let Value::Port(p)=port { if let Port::Input{text,pos,repr}=&mut *p.borrow_mut(){if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::string("set! port-position"),Value::Int(1),port.clone(),Value::string("an input port"),Value::string("an open input port")]))} *pos=n.min(text.len()); Ok(())}else{Ok(())} }else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))} }
fn b_port_position(_: &mut Evaluator,a:&[Value])->Result<Value>{ if let Value::Port(p)=&a[0]{ match &*p.borrow(){Port::Input{pos,repr,..}=>{if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("port-position"),a[0].clone(),Value::string("an input port"),Value::string("an open input port")]))} Ok(Value::Int(*pos as i64))},Port::Output{..}=>Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("port-position"),a[0].clone(),Value::string("an output port"),Value::string("an input port")]))} }else{Err(SchemeError::new("wrong-type-arg",vec![a[0].clone()]))} }
fn read_from_port(port:&Value)->Result<Value>{ if let Value::Port(p)=port{ if let Port::Input{text,pos,repr}=&mut *p.borrow_mut(){ if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("read-char"),port.clone(),Value::string("an input port"),Value::string("an open input port")]))} if *pos>=text.len(){Ok(Value::Eof)}else{let c=text[*pos]; *pos+=1; Ok(Value::Char(c))} }else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))} }else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))} }
fn b_read_char(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=a.get(0).cloned().unwrap_or_else(||ev.stdin.clone()); read_from_port(&p)}
fn b_read_byte(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=a.get(0).cloned().unwrap_or_else(||ev.stdin.clone()); if matches!(p,Value::Port(ref port) if matches!(&*port.borrow(),Port::Input{repr:PortRepr::ClosedInput,..})){return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("read-byte"),p,Value::string("an input port"),Value::string("an open input port")]))} match b_read_char(ev,a)?{Value::Char(c)=>Ok(Value::Int(c as i64)),Value::Eof=>Ok(Value::Eof),v=>Ok(v)}}
fn b_read_string_port(ev:&mut Evaluator,a:&[Value])->Result<Value>{let narg=a.get(0).ok_or_else(||SchemeError::new("wrong-number-of-args",vec![]))?; let raw_n=match narg{Value::Int(n)=>*n,_=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("read-string"),Value::Int(1),narg.clone(),Value::string(value_kind(narg)),Value::string("an integer")]))}; if raw_n<0{return Err(SchemeError::new("out-of-range",vec![Value::string("~A ~:D argument, ~S, is out of range (~A)"),Value::symbol("read-string"),Value::Int(1),Value::Int(raw_n),Value::string("it is negative")]))} let n=raw_n as usize; let p=a.get(1).cloned().unwrap_or_else(||ev.stdin.clone()); if let Value::Port(port)=&p{ let mut pb=port.borrow_mut(); if let Port::Input{text,pos,repr}=&mut *pb{ if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("read-string"),Value::Int(2),p.clone(),Value::string("an input port"),Value::string("an open input port")]))} if *pos>=text.len(){return Ok(Value::Eof);} let end=(*pos+n).min(text.len()); let s=text[*pos..end].iter().collect::<String>(); *pos=end; Ok(Value::string(s)) }else{Err(SchemeError::new("wrong-type-arg",vec![p.clone()]))} }else{Err(SchemeError::new("wrong-type-arg",vec![p]))}}
fn b_read(ev:&mut Evaluator,a:&[Value])->Result<Value>{let port=a.first().cloned().unwrap_or_else(||ev.stdin.clone());if let Value::Port(value)=&port{if let Port::Input{text,pos,repr}=&mut *value.borrow_mut(){if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("read"),port.clone(),Value::string("an input port"),Value::string("an open input port")]))}let remaining=&text[*pos..];if remaining.is_empty(){return Ok(Value::Eof)}let mut reader=Reader{chars:remaining.to_vec(),pos:0};let result=match reader.read_expr(){Ok(value)=>value,Err(error)=>{if error.tag=="read-error"&&remaining.first()==Some(&'('){let remaining=remaining.iter().collect::<String>();return Err(SchemeError::new("read-error",vec![Value::string(format!("missing close paren: {}",remaining))]))}return Err(error)}};*pos+=reader.pos;Ok(result)}else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))}}else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))}}

fn b_string_to_byte_vector(_: &mut Evaluator,a:&[Value])->Result<Value>{match &a[0]{Value::String(s)=>Ok(Value::ByteVector(Rc::new(RefCell::new(s.borrow().as_bytes().to_vec())))),v=>Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("string->byte-vector"),v.clone(),Value::string(value_kind(v)),Value::string("a string")]))}}
