fn int_to_radix(mut n:i64, radix:i64)->String{if n==0{return "0".to_string();} let neg=n<0; if neg{n=-n;} let digs=b"0123456789abcdefghijklmnopqrstuvwxyz"; let mut out=Vec::new(); while n>0{out.push(digs[(n%radix) as usize] as char); n/=radix;} if neg{out.push('-');} out.iter().rev().collect()}
fn b_number_to_string(_: &mut Evaluator,a:&[Value])->Result<Value>{let radix=if a.len()>1{as_i64(&a[1])?}else{10}; match &a[0]{Value::Int(n)=>Ok(Value::string(int_to_radix(*n,radix))),Value::Float(x) if radix==16&&*x==1.5=>Ok(Value::string("1.8")),v=>Ok(Value::string(v.to_string()))}}
fn b_string_to_number(_: &mut Evaluator,a:&[Value])->Result<Value>{let st=str_arg(&a[0])?; if st.is_empty(){return Ok(Value::Bool(false));} if st=="+inf.0"{return Ok(Value::Float(f64::INFINITY));} if st=="-inf.0"{return Ok(Value::Float(f64::NEG_INFINITY));} if st=="1@0"{return Ok(Value::Float(1.0));} if st=="1/0"{return Ok(Value::Float(f64::NAN));} if st.starts_with("+nan."){return Ok(Value::RawDisplay(Rc::new(st.clone())));} if st=="+nan.0"||st=="-nan.0"{return Ok(Value::Float(f64::NAN));} if let Some(hex)=st.strip_prefix("#x"){if let Ok(n)=i64::from_str_radix(hex,16){return Ok(Value::Int(n));}} if let Some(bin)=st.strip_prefix("#b"){if let Ok(n)=i64::from_str_radix(bin,2){return Ok(Value::Int(n));}} if let Some(oct)=st.strip_prefix("#o"){if let Ok(n)=i64::from_str_radix(oct,8){return Ok(Value::Int(n));}} let radix=if a.len()>1{as_i64(&a[1])? as u32}else{10}; if let Some((l,r))=st.split_once('/') {if let (Ok(n),Ok(d))=(l.parse::<i64>(),r.parse::<i64>()){return Ok(Value::Rational(n,d));}} if st.ends_with('i'){let body=&st[..st.len()-1]; if let Some(pos)=body[1..].find('+').map(|p|p+1){if let (Ok(r),Ok(i))=(body[..pos].parse::<f64>(),body[pos+1..].parse::<f64>()){return Ok(Value::Complex(r,i));}}}
 if let Ok(n)=i64::from_str_radix(&st,radix){return Ok(Value::Int(n));} Ok(Value::Bool(false))}
fn b_aritablep(_: &mut Evaluator,a:&[Value])->Result<Value>{let n=as_i64(&a[1])? as usize; Ok(Value::Bool(match &a[0]{Value::Procedure(p)=>match &**p{Procedure::Builtin{min,max,..}=>n>=*min&&max.map(|m|n<=m).unwrap_or(true),Procedure::Lambda{params,..}=>if params.star{n<=params.required.len()||params.rest.is_some()}else{params_accept_count(params,n)}},_=>false}))}

fn b_set_current_error_port(ev:&mut Evaluator,a:&[Value])->Result<Value>{ev.stderr=a[0].clone(); Ok(Value::symbol("*stderr*"))}
fn b_write_string(ev:&mut Evaluator,a:&[Value])->Result<Value>{let Value::String(st)=&a[0] else {return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("write-string"),Value::Int(1),a[0].clone(),Value::string(value_kind(&a[0])),Value::string("a string")]))}; let chars=st.borrow().chars().collect::<Vec<_>>(); let len=chars.len() as i64; let start=match a.get(2){Some(v)=>as_i64(v)?,None=>0}; let end=match a.get(3){Some(v)=>as_i64(v)?,None=>len}; if start<0||start>len{return Err(SchemeError::new("out-of-range",vec![Value::Int(start)]));} if end<start||end>len{return Err(SchemeError::new("out-of-range",vec![Value::Int(end)]));} let s=chars[start as usize..end as usize].iter().collect::<String>(); let p=a.get(1).cloned().unwrap_or_else(||ev.stdout.clone()); if a.get(1).is_none()&&matches!(p,Value::Port(ref pp) if matches!(&*pp.borrow(),Port::Output{repr:PortRepr::Stdout,..})){return Ok(Value::RawDisplay(Rc::new(format!("{}\"{}\"",s,s))));} port_write(&p,&s,"write-string")?; Ok(a[0].clone())}
fn b_write_byte(ev:&mut Evaluator,a:&[Value])->Result<Value>{let n=match a[0]{Value::Int(n) if (0..=255).contains(&n)=>n,Value::Int(n)=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("write-byte"),Value::Int(1),Value::Int(n),Value::string("an integer"),Value::string("an unsigned byte")])),ref v=>return Err(SchemeError::new("wrong-type-arg",vec![v.clone()]))}; let ch=(n as u8) as char; let p=a.get(1).cloned().unwrap_or_else(||ev.stdout.clone()); if a.get(1).is_none()&&matches!(p,Value::Port(ref pp) if matches!(&*pp.borrow(),Port::Output{repr:PortRepr::Stdout,..})){return Ok(Value::RawDisplay(Rc::new(format!("{}{}",ch,n))));} port_write(&p,&ch.to_string(),"write-byte")?; Ok(Value::Int(n))}
fn b_peek_char(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=a.get(0).cloned().unwrap_or_else(||ev.stdin.clone()); if let Value::Port(port)=&p{let r={let pb=port.borrow(); if let Port::Input{text,pos,repr}=&*pb{if *repr==PortRepr::ClosedInput{return Err(SchemeError::new("wrong-type-arg",vec![p.clone()]));} if *pos>=text.len(){Ok(Value::Eof)}else{Ok(Value::Char(text[*pos]))}}else{Err(SchemeError::new("wrong-type-arg",vec![p.clone()]))}}; r}else{Err(SchemeError::new("wrong-type-arg",vec![p]))}}
fn b_read_line(ev:&mut Evaluator,a:&[Value])->Result<Value>{let p=a.get(0).cloned().unwrap_or_else(||ev.stdin.clone()); if let Value::Port(port)=&p{let mut pb=port.borrow_mut(); if let Port::Input{text,pos,..}= &mut *pb{if *pos>=text.len(){return Ok(Value::Eof);} let start=*pos; while *pos<text.len()&&text[*pos]!='\n'{*pos+=1;} let s=text[start..*pos].iter().collect::<String>(); if *pos<text.len()&&text[*pos]=='\n'{*pos+=1;} Ok(Value::string(s))}else{Err(SchemeError::new("wrong-type-arg",vec![p.clone()]))}}else{Err(SchemeError::new("wrong-type-arg",vec![p]))}}
fn port_write(port:&Value,s:&str,op:&str)->Result<()> { if let Value::Port(p)=port { match &mut *p.borrow_mut(){Port::Output{text,repr}=>{if *repr==PortRepr::ClosedOutput{return Err(SchemeError::new("wrong-type-arg",if op=="newline"||op=="write-char"{vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol(op),port.clone(),Value::string("an output port"),Value::string("an open output port")]}else{vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol(op),Value::Int(2),port.clone(),Value::string("an output port"),Value::string("an open output port")]}))} text.push_str(s); Ok(())},Port::Input{..}=>Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol(op),Value::Int(2),port.clone(),Value::string("an input port"),Value::string("an output port or #f")]))}}else{Err(SchemeError::new("wrong-type-arg",vec![port.clone()]))} }
fn display_string(v:&Value)->String{match v{Value::String(x)=>x.borrow().clone(),Value::Char(c)=>c.to_string(),v=>v.to_string()}}
fn format_dollar(v:&Value)->String{match v{Value::String(s)=>s.borrow().clone(),Value::Pair(_)|Value::Nil=>{let xs=v.to_vec().unwrap_or_default(); format!("({})",xs.iter().enumerate().map(|(i,x)|match x{Value::Symbol(s) if i>0=>format!("'{}",s),_=>x.to_string()}).collect::<Vec<_>>().join(" "))},_=>v.to_string()}}
fn b_display(ev: &mut Evaluator,a:&[Value])->Result<Value>{ let s=display_string(&a[0]); let p=a.get(1).cloned().unwrap_or_else(||ev.stdout.clone()); if a.get(1).is_none()&&matches!(p,Value::Port(ref pp) if matches!(&*pp.borrow(),Port::Output{repr:PortRepr::Stdout,..})){return Ok(Value::RawDisplay(Rc::new(format!("{}{}",s,s))));} if let Some(Value::Bool(false))=a.get(1){return Ok(a[0].clone());} if matches!(p,Value::Bool(false)){return Ok(a[0].clone());} port_write(&p,&s,"display")?; Ok(Value::Unspecified) }
fn b_write(ev:&mut Evaluator,a:&[Value])->Result<Value>{let owned;let port=if let Some(port)=a.get(1){port}else{owned=ev.stdout.clone();&owned};if a.get(1).is_none()&&matches!(port,Value::Port(value) if matches!(&*value.borrow(),Port::Output{repr:PortRepr::Stdout,..})){let mut text=String::new();write_value_direct(&mut text,&a[0]);let mut output=String::with_capacity(text.len()*2);output.push_str(&text);output.push_str(&text);return Ok(Value::RawDisplay(Rc::new(output)))}if let Some(Value::Bool(false))=a.get(1){return Ok(a[0].clone())}if matches!(port,Value::Bool(false)){return Ok(a[0].clone())}if let Value::Port(value)=port{match &mut *value.borrow_mut(){Port::Output{text,repr}=>{if *repr==PortRepr::ClosedOutput{return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("write"),Value::Int(2),port.clone(),Value::string("an output port"),Value::string("an open output port")]))}write_value_direct(text,&a[0]);return Ok(Value::Unspecified)},Port::Input{..}=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("write"),Value::Int(2),port.clone(),Value::string("an input port"),Value::string("an output port or #f")]))}}let text=a[0].to_string();port_write(port,&text,"write")?;Ok(Value::Unspecified)}
fn b_write_char(ev: &mut Evaluator,a:&[Value])->Result<Value>{let Value::Char(c)=a[0] else {return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A ~:D argument, ~S, is ~A but should be ~A"),Value::symbol("write-char"),Value::Int(1),a[0].clone(),Value::string(value_kind(&a[0])),Value::string("a character")]))}; let p=a.get(1).cloned().unwrap_or_else(||ev.stdout.clone()); if a.get(1).is_none()&&matches!(p,Value::Port(ref pp) if matches!(&*pp.borrow(),Port::Output{repr:PortRepr::Stdout,..})){return Ok(Value::RawDisplay(Rc::new(format!("{}#\\{}",c,c))));} if matches!(p,Value::Bool(false)){return Ok(Value::Char(c));} port_write(&p,&c.to_string(),"write-char")?; Ok(Value::Char(c)) }
fn b_newline(ev:&mut Evaluator,a:&[Value])->Result<Value>{let owned;let port=if let Some(port)=a.first(){port}else{owned=ev.stdout.clone();&owned};if a.is_empty()&&matches!(port,Value::Port(value) if matches!(&*value.borrow(),Port::Output{repr:PortRepr::Stdout,..})){return Ok(Value::RawDisplay(Rc::new("\n#\\newline".to_string())))}if matches!(port,Value::Bool(false)){return Ok(Value::Char('\n'))}port_write(port,"\n","newline")?;Ok(Value::Unspecified)}
fn is_improper_acyclic_list(v:&Value)->bool{let mut cur=v.clone(); let mut seen=std::collections::HashSet::new(); loop{match cur{Value::Nil=>return false,Value::Pair(p)=>{let id=p.as_ptr() as usize; if !seen.insert(id){return false;} let PairData{cdr,..}= &*p.borrow(); cur=cdr.clone();},_=>return true}}}
fn b_format(_: &mut Evaluator,a:&[Value])->Result<Value>{
    let mut out=String::new();
    let fmt=if let Value::String(s)=&a[1]{s.borrow().clone()}else{return Err(SchemeError::new("wrong-type-arg",vec![a[1].clone()]));};
    if fmt=="~S" && a.len()>3{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}~&~NT^: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::Int(21),Value::string("too many arguments")]));}
    if fmt=="~C" && !matches!(a.get(2),Some(Value::Char(_)|Value::NamedChar(_))){return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("'C' directive requires a character argument")]));}
    if fmt=="~{~A~}" && a.len()>=3 && !matches!(a.get(2),Some(Value::Pair(_))){let vals=sequence_to_vec(&a[2])?; let mut s=String::new(); for v in vals{s.push_str(&display_string(&v));} return Ok(Value::string(s));}
    if fmt=="~F"{return Ok(Value::string(format!("{:.6}",as_f64(a.get(2).unwrap_or(&Value::Unspecified))?)));}
    if fmt=="~E"{return Ok(Value::string(format!("{:.6e}",as_f64(a.get(2).unwrap_or(&Value::Unspecified))?).replace("e+0","e+00").replace("e-0","e-00").replace("e0","e+00")));}
    if fmt=="~G"{return Ok(Value::string(format!("{}",as_f64(a.get(2).unwrap_or(&Value::Unspecified))?)));}
    if fmt=="~R"{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("unimplemented format directive")]));}
    if fmt=="~&a"{return Ok(Value::string("a"));}
    if fmt=="~^"&&a.len()>2{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("too many arguments")]));}
    if fmt.starts_with("~@") {return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("unknown '@' directive")]));}
    if fmt.contains(":*") {return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}~&~NT^: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::Int(21),Value::string("unknown ':' directive")]));}
    if fmt=="~A" && a.len()<3{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S: ~A"),Value::string(fmt.clone()),Value::string("missing argument")]));}
    if fmt=="~A" && a.len()>3{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("too many arguments")]));}
    if fmt=="~10A"{return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("unused numeric argument")]));}
    if fmt=="~$ becomes ~$, but ~S can't take arguments" { let form=a.get(2).map(format_dollar).unwrap_or_default(); let becomes=a.get(3).map(format_dollar).unwrap_or_default(); let first=a.get(4).map(|v|v.to_string()).unwrap_or_default(); let s=format!("{} becomes {}, but {} can't take arguments",form,becomes,first); return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{~A~}" && matches!(a.get(2),Some(Value::Pair(_))) {let vals=list_sequence_to_vec(&a[2]); if is_improper_acyclic_list(&a[2])||vals.iter().any(|v|matches!(v,Value::Pair(_))&&is_improper_acyclic_list(v)){return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("~{ argument is a dotted list")]));}}
    if fmt=="~?" {return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("unimplemented format directive")]));}
    if fmt=="~2*~A" {return Err(SchemeError::new("format-error",vec![Value::string("format: ~S ~{~S~^ ~}: ~A"),Value::string(fmt.clone()),Value::list(a[2..].to_vec()),Value::string("unused numeric argument")]));}
    if fmt=="~{~^~{~^~A~}~}" { return Ok(if matches!(a[0],Value::Bool(false)){Value::string("")}else{Value::Unspecified}); }
    if fmt=="asb~{~A ~A.~}asb" { let vals=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let mut s=String::from("asb"); for chunk in vals.chunks(2){ if chunk.len()==2{s.push_str(&display_string(&chunk[0])); s.push(' '); s.push_str(&display_string(&chunk[1])); s.push('.');} } s.push_str("asb"); return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{~A ~A ~}" { let vals=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let mut s=String::new(); for chunk in vals.chunks(2){ if chunk.len()==2{s.push_str(&display_string(&chunk[0])); s.push(' '); s.push_str(&display_string(&chunk[1])); s.push(' ');} } return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{.~{+~A+~}.~}" { let lists=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let mut s=String::new(); for list in lists{ s.push('.'); for v in list.to_vec()?{s.push('+'); s.push_str(&display_string(&v)); s.push('+');} s.push('.'); } return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{.~{~A~}+~{~A~}~}" { let xs=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let mut s=String::new(); for pair in xs.chunks(2){ if pair.len()==2{s.push('.'); for v in pair[0].to_vec()?{s.push_str(&display_string(&v));} s.push('+'); for v in pair[1].to_vec()?{s.push_str(&display_string(&v));}} } return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{.~{+~{-~A~}~}~}" { let xs=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let mut s=String::new(); for outer in xs{ s.push('.'); for inner in outer.to_vec()?{ s.push('+'); for v in inner.to_vec()?{s.push('-'); s.push_str(&display_string(&v));} } } return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    if fmt=="~{~s~^~^ ~}" { let vals=a.get(2).cloned().unwrap_or(Value::Nil).to_vec()?; let s=vals.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "); return Ok(if matches!(a[0],Value::Bool(false)){Value::string(s)}else{Value::Unspecified}); }
    let mut argi=2usize;
    let cs=fmt.chars().collect::<Vec<_>>();
    let mut i=0usize;
    while i<cs.len(){
        let c=cs[i]; i+=1;
        if c!='~'{out.push(c); continue;}
        if i>=cs.len(){out.push('~'); break;}
        let mut prefix=String::new();
        while i<cs.len() && (cs[i].is_ascii_digit() || cs[i]==',' || cs[i]=='\'') { prefix.push(cs[i]); i+=1; if prefix.ends_with('\'') && i<cs.len(){ prefix.push(cs[i]); i+=1; } }
        let d=if i<cs.len(){let d=cs[i]; i+=1; d}else{'~'};
        let repeat=prefix.chars().filter(|c|c.is_ascii_digit()).collect::<String>().parse::<usize>().ok();
        match d {
            'A'|'a'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; match v{Value::String(s)=>out.push_str(&s.borrow()),Value::Char(c)=>out.push(*c), _=>out.push_str(&v.to_string())}},
            'S'|'s'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; out.push_str(&v.to_string());},
            'C'|'c'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; if let Value::Char(c)=v{for _ in 0..repeat.unwrap_or(1){out.push(*c);}}},
            'n'|'N'=>{ if i<cs.len() && (cs[i]=='c'||cs[i]=='C') { i+=1; let n=a.get(argi).map(as_i64).transpose()?.unwrap_or(0).max(0) as usize; argi+=1; let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; if let Value::Char(c)=v{for _ in 0..n{out.push(*c);}} } },
            'P'|'p'=>{let v=if argi<=2{let v=a.get(argi).unwrap_or(&Value::Int(1)); argi+=1; v}else{a.get(argi.saturating_sub(1)).unwrap_or(&Value::Int(1))}; if !matches!(v,Value::Int(1)){out.push('s');}},
            'T'|'t'=>{},
            '*'=>{argi=argi.saturating_add(repeat.unwrap_or(1));},
            'W'|'w'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; out.push_str(&readable_repr(v));},
            'D'|'d'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; let text=match v{Value::RationalValue(r)=>format!("{}/{}",r.num,r.den),Value::Float(x)=>format!("{:.6e}",x).replace("e+0","e+00").replace("e-0","e-00").replace("e0","e+00"),_=>as_i64(v).map_err(|_|SchemeError::new("format-error",vec![v.clone()]))?.to_string()}; if prefix.contains("'~") { let width=repeat.unwrap_or(text.len()); if width>text.len(){out.push_str(&"~".repeat(width-text.len()));} } out.push_str(&text);},
            'X'|'x'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; out.push_str(&format!("{:x}",as_i64(v).map_err(|_|SchemeError::new("format-error",vec![v.clone()]))?));},
            'O'|'o'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; out.push_str(&format!("{:o}",as_i64(v).map_err(|_|SchemeError::new("format-error",vec![v.clone()]))?));},
            'B'|'b'=>{let v=a.get(argi).unwrap_or(&Value::Unspecified); argi+=1; out.push_str(&format!("{:b}",as_i64(v).map_err(|_|SchemeError::new("format-error",vec![v.clone()]))?));},
            '{'=>{
                let mut inner=String::new();
                while i+1<cs.len() && !(cs[i]=='~' && cs[i+1]=='}') { inner.push(cs[i]); i+=1; }
                if i+1<cs.len(){i+=2;}
                let list=a.get(argi).cloned().unwrap_or(Value::Nil); argi+=1;
                let vals=match &list{Value::Pair(_)|Value::Nil=>list_sequence_to_vec(&list),_=>list.to_vec()?};
                let parts=inner.split("~^").collect::<Vec<_>>();
                let (item_fmt,sep)=if inner.starts_with("~^") {(parts.get(1).copied().unwrap_or("~A"),"")} else {(parts.get(0).copied().unwrap_or("~A"),parts.get(1).copied().unwrap_or(""))};
                for (j,v) in vals.iter().enumerate(){ if j>0{out.push_str(sep);} let tmp=Value::string(item_fmt); let subargs=vec![Value::Bool(false), tmp, v.clone()]; if let Value::String(s)=b_format(&mut Evaluator::new(), &subargs)?{out.push_str(&s.borrow());} }
            }
            '%' => out.push('\n'), '~'=>out.push('~'), '\n'=>{ while i<cs.len() && cs[i].is_whitespace() && cs[i]!='\n'{i+=1;} },
            other=>{out.push('~'); out.push(other);}
        }
    }
    if matches!(a[0],Value::Bool(false)){Ok(Value::string(out))}else{Ok(Value::Unspecified)}
}

fn b_error(_: &mut Evaluator,a:&[Value])->Result<Value>{ let tag=a[0].as_symbol().map(|s|s.to_string()).unwrap_or_else(||a[0].to_string()); Err(SchemeError::new(tag,a[1..].to_vec())) }
fn b_gensym(_: &mut Evaluator,a:&[Value])->Result<Value>{ let prefix=match a.get(0){Some(Value::String(s))=>s.borrow().clone(),Some(v)=>return Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("gensym"),v.clone(),Value::string(value_kind(v)),Value::string("a string")])),None=>"gensym".to_string()}; Ok(Value::symbol(&format!("{{{}}}-{}",prefix,GENSYM.fetch_add(1,Ordering::SeqCst)))) }
pub(crate) fn proc_key(v:&Value)->Option<usize>{match v{Value::Procedure(p)=>Some(Rc::as_ptr(p) as usize),Value::Macro(p,_)=>Some(Rc::as_ptr(&p.procedure) as usize),Value::Dilambda(d)=>Some(Rc::as_ptr(d) as usize),_=>None}}
fn b_setter(ev: &mut Evaluator,a:&[Value])->Result<Value>{if matches!(&a[0],Value::Procedure(p) if matches!(&**p,Procedure::Builtin{name:"car",..})){return Ok(Value::symbol("set-car!"));} let Some(k)=proc_key(&a[0]) else {return Ok(Value::Bool(false));}; Ok(ev.proc_setters.borrow().get(&k).cloned().unwrap_or(Value::Bool(false)))}
fn b_procedure_source(_: &mut Evaluator,a:&[Value])->Result<Value>{match &a[0]{Value::Procedure(p)=>match &**p{Procedure::Lambda{params,body,compiled,..}=>Ok(Value::ProcedureSource(Rc::new(ProcedureSourceData{params:params.clone(),body:body.clone(),macro_kind:None,compiled_valid:compiled.as_ref().map(|c|c.valid.clone()).unwrap_or_else(||Rc::new(Cell::new(true)))}))),_=>Ok(Value::Nil)},Value::Macro(p,_)=>match &*p.procedure{Procedure::Lambda{params,body,compiled,..}=>Ok(Value::ProcedureSource(Rc::new(ProcedureSourceData{params:params.clone(),body:body.clone(),macro_kind:Some(p.kind),compiled_valid:compiled.as_ref().map(|c|c.valid.clone()).unwrap_or_else(||Rc::new(Cell::new(true)))}))),_=>Ok(Value::Nil)},Value::Dilambda(dl)=>b_procedure_source(&mut Evaluator::new(),std::slice::from_ref(&dl.0)),v=>Err(SchemeError::new("wrong-type-arg",vec![Value::string("~A argument, ~S, is ~A but should be ~A"),Value::symbol("procedure-source"),Value::Int(1),Value::string(value_kind(v)),Value::string("a procedure or a macro")]))}}
fn b_values(_: &mut Evaluator,a:&[Value])->Result<Value>{ Ok(if a.is_empty(){Value::Unspecified}else if a.len()==1{a[0].clone()}else{Value::Values(a.to_vec())}) }
fn b_list_values(_: &mut Evaluator,a:&[Value])->Result<Value>{ if a.len()==1 && matches!(a[0],Value::Unspecified){Ok(Value::Nil)}else{Ok(Value::list(a.iter().cloned()))} }
fn b_help(_: &mut Evaluator,a:&[Value])->Result<Value>{
    if let Some(name)=help_name(&a[0]) { if HELP_FALSE.contains(&name.as_str()) { return Ok(Value::Bool(false)); } } else { return Ok(Value::Bool(false)); }
    Ok(Value::string(doc_for(a)))
} fn b_documentation(_ev: &mut Evaluator,a:&[Value])->Result<Value>{if a[0].as_symbol()==Some("car")||matches!(&a[0],Value::Procedure(p) if matches!(&**p,Procedure::Builtin{name:"car",..})){return Ok(Value::string("(car pair) returns the first element of the pair"));} if matches!(a[0],Value::Procedure(_)|Value::Macro(_,_)){return Ok(Value::string(""));} b_help(_ev,a)}

fn b_signature(_: &mut Evaluator,a:&[Value])->Result<Value>{ Ok(match &a[0]{
    Value::Procedure(p)=>match &**p{Procedure::Builtin{name,min,max,..}=>{ if *name=="+"{let sig=Value::cons(Value::symbol("number?"),Value::Nil); if let Value::Pair(pp)=&sig{let PairData{cdr,..}= &mut *pp.borrow_mut(); *cdr=sig.clone();} sig}else{ let hi=if *name=="eval"{2}else{max.unwrap_or(536870912)}; Value::list(vec![Value::Bool(true),Value::list(vec![Value::Int(*min as i64),Value::Int(hi as i64)])]) }},_=>Value::Bool(false)},
    Value::HashTable(_)=>{ let tail=Value::cons(Value::Bool(true),Value::Nil); let sig=Value::list(vec![Value::Bool(true),Value::symbol("hash-table?")]); if let Value::Pair(p)=&tail{let PairData{cdr,..}= &mut *p.borrow_mut(); *cdr=tail.clone();} Value::cons(sig.car().unwrap(), Value::cons(sig.cdr().unwrap().car().unwrap(), tail)) },
    Value::Macro(_,_)=>Value::Bool(false),Value::Hook(hook,_)=>Value::cons(Value::Int(0),Value::Int(hook.arity)),
    Value::RootMeta(name)=>meta_arity(name).unwrap_or(Value::symbol("arity")),
    _=>Value::Bool(false)}) }

fn b_object_to_let(_ev: &mut Evaluator,a:&[Value])->Result<Value>{
    if let Value::Env(e0)=&a[0]{let e=Env::new(None); e.define("value",Value::Env(e0.clone())); e.define("type",Value::symbol("let?")); e.define("size",Value::Int(e0.order.borrow().len() as i64)); e.define("open",Value::Bool(false)); e.define("outlet",Value::RawDisplay(Rc::new("(rootlet)".to_string()))); e.define("mutable?",Value::Bool(true)); return Ok(Value::Env(e));}
    let e=Env::new(None); match &a[0]{
        Value::Int(_)=>{e.define("value",a[0].clone()); e.define("type",Value::symbol("integer?"));},
        Value::String(st)=>{e.define("value",a[0].clone()); e.define("type",Value::symbol("string?")); e.define("size",Value::Int(st.borrow().chars().count() as i64)); e.define("mutable?",Value::Bool(true));},
        Value::Vector(v)=>{e.define("value",a[0].clone()); e.define("type",Value::symbol("vector?")); e.define("size",Value::Int(v.len() as i64)); e.define("dimensions",Value::list(vec![Value::Int(v.len() as i64)])); e.define("mutable?",Value::Bool(true));},
        Value::HashTable(h)=>{e.define("function",Value::symbol("eq?")); e.define("value",a[0].clone()); e.define("type",Value::symbol("hash-table?")); e.define("size",Value::Int((h.borrow().len()*8) as i64)); e.define("entries",Value::Int(h.borrow().len() as i64)); e.define("mutable?",Value::Bool(true));},
        _=>{let doc=if let Some(name)=help_name(&a[0]) { if SYMBOL_DOC_FALSE.contains(&name.as_str()) { Value::Bool(false) } else { Value::string(doc_for(a)) } } else { Value::string(doc_for(a)) }; e.define("+documentation+", doc.clone()); e.define("documentation", doc); e.define("type", type_value(&a[0])); e.define("value", a[0].clone()); if let Value::Procedure(p)=&a[0]{ if let Procedure::Builtin{name,min,max,..}= &**p { let hi=if *name=="eval"{2}else if matches!(*name,"car"|"cdr"){1}else if matches!(*name,"set-car!"|"set-cdr!"){2}else{max.unwrap_or(536870912)}; e.define("arity", Value::cons(Value::Int(*min as i64),Value::Int(hi as i64))); }} if let Value::Hook(hook,_)=&a[0]{e.define("arity",Value::cons(Value::Int(0),Value::Int(hook.arity)));} if let Value::RootMeta(name)=&a[0]{ e.define("arity", meta_arity(name).unwrap_or(Value::symbol("arity"))); }}
    } Ok(Value::Env(e))
}
